<script lang="ts">
 import {onDestroy,onMount} from 'svelte';
 import {user,userReady} from '$lib/stores/user';
 import MedicineCalendar from '$lib/components/MedicineCalendar.svelte';
 import MedicineProgress from '$lib/components/MedicineProgress.svelte';
 import {SPECIALTIES,DOMAIN_LABELS,SOURCE_PORTALS,DOMAINS} from '$lib/medicine/catalogue';
 import {emptyState,rankSpecialties,specialtyScore,caseRequest,makePrompt,validatePatch,assessmentScore,elapsed,dueGaps,gapDueAt,gapDue,type Gap,type Patch,type Request,type CaseLog} from '$lib/medicine/study';
 import {subscribeMedicine,importCase,changeTimer,readCases,backupMedicine} from '$lib/medicine/repository';
 let state=emptyState(),gaps:Gap[]=[],history:CaseLog[]=[],loadedUid='',loadedHistoryKey='',loading=true,busy=false,error='',notice='',tab='case',mode:'balanced'|'weakness'='balanced',selectedId='',setting:Request['setting']='primary-care',studyMode:Request['mode']='case',prompt='',prepared:Request|null=null,patchText='',preview:Patch|null=null,now=Date.now(),search='';
 let unsubscribe:(()=>void)|undefined,request=0;
 $: uid=$user?.uid as string|undefined;
 $: if($userReady&&uid&&uid!==loadedUid){unsubscribe?.();loadedUid=uid;loading=true;state=emptyState();gaps=[];history=[];prepared=null;patchText='';preview=null;prompt='';loadedHistoryKey='';unsubscribe=subscribeMedicine(uid,s=>{state=s;loading=false;},g=>gaps=g,e=>{error=e.message;loading=false;});}
 $: if($userReady&&!uid){unsubscribe?.();unsubscribe=undefined;loadedUid='';state=emptyState();gaps=[];history=[];loading=false;request++;}
 $: ranked=rankSpecialties(state,gaps,now,mode);
 $: selected=SPECIALTIES.find(s=>s.id===selectedId)??ranked[0];
 $: openGaps=gaps.filter(g=>!g.resolvedAt);
 $: due=dueGaps(gaps,now);
 $: activeMode=state.timer?.request.mode??studyMode;
 $: critical=openGaps.filter(g=>g.priority==='critical').length;
 $: explored=Object.keys(state.specialties).length;
 $: timerSeconds=state.timer?elapsed(state.timer,now):0;
 $: if(uid&&tab==='history'&&loadedHistoryKey!==`${uid}:${state.caseCount}`)loadHistory();
 $: filteredHistory=[...history].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).filter(h=>`${h.patch.caseTitle} ${h.patch.caseSummary} ${h.patch.specialtyId}`.toLowerCase().includes(search.toLowerCase()));
 $: chartDays=dayCounts(history);
 $: maximum=Math.max(1,...chartDays.map(d=>d.count));
 onMount(()=>{const id=setInterval(()=>now=Date.now(),1000);return()=>clearInterval(id);});
 onDestroy(()=>{unsubscribe?.();request++;});
 const title=(id:string)=>SPECIALTIES.find(s=>s.id===id)?.title??id;
 const duration=(seconds:number)=>`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;
 async function act(task:()=>Promise<unknown>,success:string){if(!uid||busy)return;busy=true;error='';notice='';try{await task();notice=success;}catch(e){error=e instanceof Error?e.message:'Speichern fehlgeschlagen. Bitte erneut versuchen.';}finally{busy=false;}}
 async function copy(){
  if(!uid||busy)return;
  prepared=state.timer?.request??caseRequest(state,selected.id,setting,`medicine-${crypto.randomUUID()}`,studyMode);
  prompt=makePrompt(state,gaps,prepared);
  try{await navigator.clipboard.writeText(prompt);}catch{error='Die Zwischenablage ist nicht verfügbar. Kopiere den Prompt unten manuell und starte den Timer separat.';return;}
  await act(()=>changeTimer(uid!,'start',prepared!),'Fallprompt kopiert · Lernzeit läuft.');
 }
 async function start(){prepared=state.timer?.request??(prepared?.specialtyId===selected.id&&prepared.setting===setting&&(prepared.mode??'case')===studyMode?prepared:caseRequest(state,selected.id,setting,`medicine-${crypto.randomUUID()}`,studyMode));await act(()=>changeTimer(uid!,'start',prepared!),'Fall-Timer gestartet.');}
 function inspect(){preview=null;error='';notice='';try{preview=validatePatch(JSON.parse(patchText.trim().replace(/^```(?:json)?\s*/,'').replace(/\s*```$/,'')));}catch(e){error=e instanceof SyntaxError?'Der Patch ist kein gültiges JSON. Bitte vollständig kopieren.':e instanceof Error?e.message:'Ungültiges JSON.';}}
 async function apply(){if(!preview||busy)return;const patch=preview;const endsTimer=state.timer?.request.id===patch.id;await act(async()=>{if(!await importCase(uid!,patch,gaps))throw new Error('Dieser Fall wurde bereits importiert. Nichts wurde doppelt gezählt.');preview=null;patchText='';prepared=null;},endsTimer?'Fall, Lücken und Lernzeit gespeichert · Session beendet.':'Fall, Quellenangaben und Lernlücken gespeichert.');}
 async function submitPatch(){if(busy)return;inspect();if(preview)await apply();}
 function patchKey(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing&&!e.ctrlKey&&!e.altKey&&!e.metaKey){e.preventDefault();void submitPatch();}}
 async function upload(e:Event){const file=(e.currentTarget as HTMLInputElement).files?.[0];if(!file)return;if(file.size>1000000){error='Bitte eine JSON-Datei unter 1 MB wählen.';return;}patchText=await file.text();await submitPatch();}
 async function loadHistory(){const token=++request,owner=uid!;loadedHistoryKey=`${owner}:${state.caseCount}`;try{const value=await readCases(owner);if(token===request&&uid===owner)history=value;}catch(e){if(token===request)error='Der Verlauf konnte nicht geladen werden. Erneut öffnen zum Wiederholen.';loadedHistoryKey=`${owner}:${state.caseCount}`;}}
 function download(name:string,text:string,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
 function exportGaps(){const clean=(s:string)=>s.replace(/[\t\r\n]+/g,' ').replace(/[<>]/g,'');download('medizin-lernlücken.tsv',openGaps.map(g=>`${clean(g.prompt)}\t${clean(g.answer)}\tMedicine::${g.specialtyId} ${g.priority}`).join('\n'),'text/tab-separated-values');}
 function dayCounts(logs:CaseLog[]){const map=new Map<string,{date:string;count:number;scores:number[]}>();for(const l of logs){const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Prague',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(l.createdAt));const day=map.get(date)??{date,count:0,scores:[]};day.count++;for(const a of l.patch.assessments){const score=assessmentScore(a);if(score!==undefined)day.scores.push(score);}map.set(date,day);}return [...map.values()].sort((a,b)=>a.date.localeCompare(b.date));}
</script>
<svelte:head><title>Medizin · Trackr</title><meta name="description" content="Fallbasiertes klinisches Lernen, Fachlandkarte, quellenbasierte Rückmeldung und gezielte Wissenslücken."/></svelte:head>
<main class="medicine">
 <header><div><h1>Klinisch denken.<br/>Wissen behalten.</h1><p>Eine fiktive Patientenvorstellung. Deine Entscheidungen.<br/>Breites Klinikwissen, das mit dir weiterwächst.</p></div><div class="total"><strong>{state.caseCount}</strong><span>Fälle dokumentiert</span><small>{Math.floor(state.studySeconds/60)} Minuten Lernzeit gespeichert</small></div></header>
 {#if loading}<p role="status">Dein Medizin-Lernbereich wird geladen…</p>{:else if !uid}<p>Bitte anmelden, um Fälle und Lernfortschritt auf deinen Geräten zu speichern.</p>{:else}
 <nav class="views" aria-label="Medizin-Ansichten">{#each [['case','Nächster Fall'],['map','Fachlandkarte'],['gaps',`Lücken (${openGaps.length})`],['history','Verlauf & Quellen'],['calendar','Kalender']] as [id,label]}<button class:active={tab===id} aria-pressed={tab===id} on:click={()=>tab=id}>{label}</button>{/each}</nav>
 {#if state.timer}<section class="timer"><div><span>{state.timer.status==='paused'?'Pause':'Fall läuft'} · {title(state.timer.specialtyId)}</span><strong>{duration(timerSeconds)}</strong></div><div class="buttons"><button disabled={busy} on:click={()=>act(()=>changeTimer(uid!,state.timer?.status==='running'?'pause':'resume'),'Timer aktualisiert.')}>{state.timer.status==='running'?'Pause':'Fortsetzen'}</button><button disabled={busy} on:click={()=>act(async()=>{await changeTimer(uid!,'finish');prepared=null;},'Aktive Lernzeit gespeichert.')}>Beenden & Zeit speichern</button><button disabled={busy} on:click={()=>act(async()=>{await changeTimer(uid!,'cancel');prepared=null;},'Timer verworfen; Lernfortschritt bleibt erhalten.')}>Abbrechen</button></div></section>{/if}
 {#if error}<p class="error" role="alert">{error}<button on:click={()=>error=''}>Schließen</button></p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
 {#if tab==='case'}
 <div class="case-layout"><section class="case-start"><div class="heading-line"><h2>{activeMode==='rapid'?'Die nächste Kurzvignette':'Der nächste klinische Fall'}</h2><span>{activeMode==='rapid'?'Etwa 5–8 Minuten':'Etwa 15–20 Minuten'}</span></div><div class="mode-switch" role="group" aria-label="Lernmodus"><button disabled={!!state.timer} class:active={studyMode==='case'} aria-pressed={studyMode==='case'} on:click={()=>{studyMode='case';prepared=null;prompt='';}}>Patientensimulation</button><button disabled={!!state.timer} class:active={studyMode==='rapid'} aria-pressed={studyMode==='rapid'} on:click={()=>{studyMode='rapid';prepared=null;prompt='';}}>Schnelle Vignette</button></div><p>{activeMode==='rapid'?'Kurzer Patientenfall, 4–6 gezielte offene Fragen. Knapp antworten, Rückmeldung erhalten, Lücken erkennen. Eine Stichprobe – keine vollständige Fachprüfung.':'Anamnese, gezielte Untersuchung und Diagnostik, Behandlung, Verlauf und sichere Grenzen – im Gespräch statt als Lernliste.'}</p><p class="small">{due.length} {due.length===1?'Lücke ist':'Lücken sind'} zur Wiederholung fällig. Fällige Lücken werden in passenden Fällen geprüft, bevor neue Fachgebiete folgen.</p>
 <div class="settings"><label>Fokus<select bind:value={mode} on:change={()=>selectedId=''}><option value="balanced">Breite erhalten</option><option value="weakness">Schwächen vertiefen</option></select></label><label>Fach<select bind:value={selectedId}><option value="">Automatisch priorisieren</option>{#each SPECIALTIES as s}<option value={s.id}>{s.title}</option>{/each}</select></label><label>Versorgung<select bind:value={setting}><option value="primary-care">Hausärztlich / ambulant</option><option value="acute">Akutversorgung / Klinik</option><option value="mixed">Gemischt</option></select></label></div>
 <div class="next"><span>{state.timer?'Aktueller Fall':selectedId?'Ausgewähltes Fach':'Als Nächstes empfohlen'}</span><h3>{title(state.timer?.specialtyId??selected.id)}</h3><p>{state.specialties[selected.id]?`${state.specialties[selected.id].cases} dokumentierte Fallbeobachtungen. Neue Anlässe und zeitversetzte Wiederholung vertiefen das Bild.`:'Hier fehlt noch eine aktuelle Fallbeobachtung. Wir beginnen ohne vorgegebenes Mastery-Rating.'}</p></div>
 {#if state.timer&&state.lastCaseId===state.timer.request.id}<p class="notice">Dieser Fall ist bereits gespeichert. Beende den Timer, bevor du den nächsten Fall beginnst.</p>{/if}
 <div class="buttons"><button class="primary" disabled={busy||!!state.timer&&state.lastCaseId===state.timer.request.id} on:click={copy}>{state.timer?'Aktuellen Fallprompt kopieren':activeMode==='rapid'?'Vignettenprompt kopieren & Timer starten':'Fallprompt kopieren & Timer starten'}</button><button disabled={busy} on:click={start}>Nur Timer starten</button></div>
 <p class="small">Der Fall wird im Study-Chat simuliert. Erst selbst entscheiden, dann gezielt korrigieren und im nächsten Kontext anwenden.</p>
 {#if prompt}<details><summary>Prompt anzeigen / manuell kopieren</summary><textarea readonly value={prompt} aria-label="Medizin-Fallprompt"></textarea></details>{/if}
 <section class="patch"><h3>Den Fall zurückbringen</h3><p>Der Chat schließt mit einem Medizin-Patch. Einfügen und Enter drücken: Fall speichern und zugehörige Session beenden. Lernzeit wird dabei automatisch gesichert. Shift+Enter fügt eine neue Zeile ein.</p><textarea bind:value={patchText} on:input={()=>preview=null} on:keydown={patchKey} aria-label="Medizin-Patch" placeholder="Patch einfügen → Enter zum Speichern. Shift+Enter: neue Zeile."></textarea><div class="buttons"><button disabled={busy||!patchText.trim()} on:click={inspect}>Patch prüfen</button><label class="upload">JSON-Datei wählen<input type="file" accept=".json,application/json" on:change={upload}/></label></div>{#if preview}<div class="preview"><h4>{preview.caseTitle}</h4><p>{preview.caseSummary}</p><ul>{#each preview.assessments as a}<li>{title(a.specialtyId)}: {assessmentScore(a)===undefined?'Teilbewertung':`${assessmentScore(a)}/20 im Fall`}{a.safetyCriticalError?' · Sicherheitsfehler':''}</li>{/each}</ul><p>{preview.addGaps.length} neue Lücken · {preview.gapResults.length} Lückentests · {preview.sources.length} Quellenangaben</p><button class="primary" disabled={busy} on:click={apply}>Fall-Patch übernehmen</button></div>{/if}</section>
 </section><aside><h2>Deine klinische Breite</h2><div class="breadth"><strong>{explored}<small> / {SPECIALTIES.length}</small></strong><span>Fachgebiete im Fall beobachtet</span></div><p class="small">Innere Medizin, operative Fächer, Kinder, Schwangerschaft, Psyche, Sinnesorgane und mehr. Fachübergreifende Fälle verbinden sie.</p><h3>Aktuell priorisiert</h3>{#each ranked.slice(0,4) as s}<button class="queue" on:click={()=>selectedId=s.id}><span>{s.title}</span><small>{specialtyScore(state,s.id)===undefined?'Noch keine vollständige Fallbewertung':`${specialtyScore(state,s.id)!.toFixed(1)}/20 · ${state.specialties[s.id]?.cases??0} Fallbeobachtungen`}</small></button>{/each}<p class="small">{mode==='balanced'?'Fällige Lücken zuerst; danach unbeobachtete Fachgebiete, niedrige Fallleistung und längere Lernpause.':'Fällige Lücken zuerst; Sicherheitslücken, schwache und ältere Beobachtungen wiegen stärker.'}</p><div class="critical"><strong>{critical}</strong><span>offene sicherheitsrelevante Lernlücken</span></div><h3>Quellen statt Gewissheit vortäuschen</h3><p class="small">Der Tutor muss Unterlagen tatsächlich lesen und aktuelle Empfehlungen mit genauer Fundstelle prüfen. Ohne Zugriff werden quellenabhängige Aussagen und entsprechende Bewertungen ausgelassen.</p><div class="portal-links">{#each SOURCE_PORTALS as source}<a href={source.url} target="_blank" rel="noopener noreferrer">{source.title}</a>{/each}</div></aside></div>
 {:else if tab==='map'}<MedicineProgress {state} onchoose={id=>{selectedId=id;tab='case';}}/>
 {:else if tab==='calendar'}{#key uid}<MedicineCalendar {uid}/>{/key}
 {:else if tab==='gaps'}<section class="gap-page"><div class="heading-line"><h2>Gezielt nachschärfen.</h2><button disabled={!openGaps.length} on:click={exportGaps}>Lücken für Anki exportieren</button></div><p class="small">Erster Test frühestens nach drei Tagen. Selbstständig richtig: aus der aktiven Liste geschlossen. Falsch: gleicher Eintrag, nächste Prüfung drei Tage später. Erklärungen allein schließen nichts. Historie bleibt erhalten; der Chat erhält maximal drei fällige Lücken und einen begrenzten Abgleich vorhandener Einträge.</p>{#each [...openGaps].sort((a,b)=>Number(gapDue(b,now))-Number(gapDue(a,now))||gapDueAt(a).localeCompare(gapDueAt(b))) as g}<details><summary><span class:danger={g.priority==='critical'}>{g.prompt}<small>{title(g.specialtyId)} · {g.priority==='critical'?'sicherheitsrelevant':g.priority==='important'?'klinischer Kern':'Detail'} · {gapDue(g,now)?'Jetzt fällig':`Prüfung ab ${new Date(gapDueAt(g)).toLocaleDateString('de-DE')}`}</small></span></summary><p>{g.answer}</p><button on:click={()=>{selectedId=g.specialtyId;mode='weakness';tab='case';}}>In einem neuen Fall üben</button></details>{:else}<div class="empty">Noch keine offenen Lernlücken. Der erste Fall-Patch erfasst konkrete Wissens- und Entscheidungsprobleme.</div>{/each}</section>
 {:else}<section class="history"><div class="heading-line"><h2>Beobachtungen, die bleiben.</h2><button disabled={busy} on:click={loadHistory}>Verlauf neu laden</button></div><p class="small">Lernfälle und Quellenprotokolle bleiben erhalten. Werte beschreiben die beobachteten Fälle, nicht deine gesamte klinische Kompetenz.</p>{#if chartDays.length}<div class="chart"><h3>Fälle je Lerntag</h3><svg viewBox="0 0 640 150" role="img" aria-label="Dokumentierte klinische Fälle pro Lerntag">{#each chartDays as d,i}<rect x={24+i*590/chartDays.length} y={125-d.count/maximum*100} width={Math.max(2,Math.min(35,580/chartDays.length))} height={d.count/maximum*100} rx="2"><title>{d.date}: {d.count} Fälle</title></rect>{/each}<line x1="20" x2="620" y1="125" y2="125"/><text x="20" y="147">{chartDays[0].date}</text><text x="620" y="147" text-anchor="end">{chartDays[chartDays.length-1].date}</text></svg><details><summary>Dokumentierte Tageswerte</summary>{#each chartDays as d}<p>{d.date}: {d.count} Fälle · {d.scores.length?`${(d.scores.reduce((n,v)=>n+v,0)/d.scores.length).toFixed(1)}/20 durchschnittliche vollständige Fallbewertung`:'nur Teilbewertungen'}</p>{/each}</details></div>{/if}
 <label class="search">Fälle durchsuchen<input type="search" bind:value={search} placeholder="Falltitel, Fach oder Zusammenfassung"/></label><p class="small">Bis zu 30 passende Einträge; der vollständige Verlauf ist im Backup enthalten. Quellenangaben sind Angaben des Tutors und werden von Trackr nicht unabhängig inhaltlich verifiziert.</p>{#each filteredHistory.slice(0,30) as h}<details><summary>{h.patch.caseTitle}<small>{new Date(h.createdAt).toLocaleDateString('de-DE')} · {title(h.patch.specialtyId)} · {h.patch.mode==='rapid'?'Kurzvignette':'Patientensimulation'}</small></summary><p>{h.patch.caseSummary}</p>{#each h.patch.assessments as a}<h4>{title(a.specialtyId)} · {assessmentScore(a)===undefined?'Teilbewertung':`${assessmentScore(a)}/20 im Fall`}</h4><p>{a.evidence}</p><div class="domain-evidence">{#each DOMAINS as d}<span>{DOMAIN_LABELS[d]}: {a.ratings[d]??'ungeprüft'}</span>{/each}</div>{/each}<h4>Quellenprotokoll des Tutors</h4>{#each h.patch.sources as s}<div class="source"><strong>{s.title}</strong><span>{s.locator}</span><span>{s.access==='opened'?'Laut Tutor geöffnet':'Nicht zugänglich'} · {s.checkedAt}</span><p>{s.supports}</p>{#if s.url}<a href={s.url} target="_blank" rel="noopener noreferrer">Quelle öffnen</a>{/if}</div>{:else}<p>Keine zugänglichen Quellen protokolliert. Keine belegte vollständige Behandlungs-/Sicherheitsbewertung.</p>{/each}</details>{:else}<div class="empty">Hier erscheinen deine gespeicherten Fälle mit eigenständiger Leistung, Lernbedarf und Quellenangaben.</div>{/each}</section>{/if}
 <footer><span>Klinische Fächer einschließlich klinischer Diagnostik. Keine separaten Public-Health-, Hygiene- oder Epidemiologie-Lernblöcke.</span><button disabled={busy} on:click={()=>act(async()=>download('trackr-medicine-backup.json',JSON.stringify(await backupMedicine(uid!,state,gaps),null,2)),'Medizin-Backup heruntergeladen.')}>Vollständiges Backup</button></footer>
 {/if}
</main>
<style>
 .medicine{--fg:#edf0f6;--muted:#adb7c9;--line:#303b4d;--accent:#b4adff;color:var(--fg);max-width:1360px;margin:auto;padding:28px 20px 100px;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}.medicine ::selection{background:#51486e;color:white}.medicine :global(:focus-visible){outline:2px solid #c6beff;outline-offset:4px}h1{font-size:clamp(2.4rem,5vw,3.8rem);letter-spacing:-.03em;line-height:1.07;margin:0 0 16px;text-wrap:balance}h2{font-size:1.35rem;letter-spacing:-.02em;margin:0 0 12px}h3{font-size:1rem;margin:22px 0 10px}h4{font-size:.9rem;margin:18px 0 8px}p{max-width:72ch;line-height:1.65;color:var(--muted);font-size:.88rem}header{display:flex;justify-content:space-between;align-items:flex-end;gap:28px;margin:12px 0 30px}header p{margin:0}.total{display:grid;gap:5px;min-width:175px;color:var(--muted);font-size:.8rem}.total strong{font-size:2rem;color:var(--fg);font-variant-numeric:tabular-nums}.total small{font-size:.72rem}.views{display:flex;gap:6px;flex-wrap:wrap;border-block:1px solid var(--line);padding:12px 0;margin:22px 0 28px}button,select,input,textarea{font:inherit}button,.upload{min-height:44px;border:1px solid var(--line);border-radius:8px;background:#1d2533;color:#e9ecf5;padding:10px 14px;font-size:.82rem;cursor:pointer;touch-action:manipulation}button{transition:background-color 140ms ease-out,transform 120ms ease-out}button:active{transform:scale(.985)}button:disabled{opacity:.5;cursor:not-allowed}.views button{border-color:transparent;background:none}.views button.active{background:#383248;color:#e9e4ff}.primary{background:var(--accent);border-color:var(--accent);color:#1b1631;font-weight:700}.buttons{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.case-layout{display:grid;grid-template-columns:minmax(0,1fr) 290px;gap:44px}.case-start{min-width:0}.mode-switch{display:flex;gap:6px;flex-wrap:wrap;margin:18px 0}.mode-switch button.active{background:#383248;border-color:#9385c9;color:#e9e4ff}.heading-line{display:flex;justify-content:space-between;align-items:center;gap:16px}.heading-line>span{font-size:.74rem;color:var(--muted)}.settings{display:grid;grid-template-columns:1fr 1.2fr;gap:12px;margin:24px 0}.settings label:last-child{grid-column:1/-1}label{display:grid;gap:7px;color:var(--muted);font-size:.78rem}select,input{box-sizing:border-box;background:#171f2c;color:var(--fg);border:1px solid var(--line);border-radius:8px;padding:10px;font-size:16px;min-height:44px;width:100%;min-width:0}textarea{box-sizing:border-box;display:block;width:100%;min-height:170px;resize:vertical;background:#111824;color:var(--fg);border:1px solid var(--line);border-radius:9px;font-size:16px;padding:14px;line-height:1.5;caret-color:var(--accent)}textarea::placeholder,input::placeholder{color:#9da8bc}.next{background:#171d2a;border:1px solid var(--line);border-radius:12px;padding:20px;margin:20px 0}.next>span{color:#b9b0e2;font-size:.75rem}.next h3{margin:9px 0;font-size:1.35rem}.next p{font-size:.82rem;margin:8px 0 0}.small{font-size:.76rem;line-height:1.65}.patch{border-top:1px solid var(--line);margin-top:28px;padding-top:6px}.upload{display:inline-flex;align-items:center}.upload input{position:absolute;opacity:0;width:1px;height:1px;min-height:0}.upload:focus-within{outline:2px solid var(--accent);outline-offset:3px}.preview{background:#252238;border-radius:10px;padding:16px;margin-top:16px}.preview h4{margin-top:0}.preview ul{font-size:.83rem;line-height:1.7;padding-left:20px}aside{padding-left:24px;border-left:1px solid var(--line)}.breadth{display:grid;gap:5px;padding:10px 0}.breadth strong{font-size:2rem;font-variant-numeric:tabular-nums}.breadth small{font-size:1rem;color:var(--muted)}.breadth>span{font-size:.74rem;color:var(--muted)}.queue{display:grid;gap:6px;text-align:left;width:100%;background:none;border-color:transparent;border-bottom:1px solid var(--line);border-radius:0;padding:12px 0}.queue span{font-size:.82rem}.queue small{color:var(--muted);font-size:.67rem;line-height:1.5}.critical{display:flex;gap:12px;align-items:center;margin:22px 0;color:#e4b7c2;font-size:.75rem}.critical strong{font-size:1.5rem}.portal-links{display:grid;gap:10px;font-size:.77rem}a{color:#c8c0ff;text-underline-offset:3px;overflow-wrap:anywhere}.timer{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:16px 20px;border:1px solid var(--line);border-radius:12px;margin:0 0 22px;background:#171e2b}.timer>div:first-child{display:grid;gap:6px}.timer span{font-size:.78rem;color:var(--muted)}.timer strong{font-size:1.8rem;font-variant-numeric:tabular-nums}.notice{color:#b4e3cd}.error{border:1px solid #a96e7f;color:#ffc3d2;padding:12px;border-radius:9px;display:flex;align-items:center;justify-content:space-between;gap:14px}details{border-bottom:1px solid var(--line);padding:16px 0}summary{cursor:pointer;min-height:28px;font-size:.9rem;line-height:1.5}summary small{display:block;color:var(--muted);font-size:.7rem;margin-top:5px}.danger{color:#ffc2ce}.empty{padding:28px 20px;background:#151c29;color:var(--muted);font-size:.88rem;border-radius:12px;line-height:1.6;margin-top:20px}.source{padding:12px 0 16px;border-bottom:1px solid var(--line);display:grid;gap:5px;font-size:.8rem}.source span{color:var(--muted)}.source p{margin:5px 0;font-size:.8rem}.domain-evidence{display:flex;flex-wrap:wrap;gap:12px;font-size:.72rem;color:var(--muted)}.chart{margin:24px 0}.chart svg{width:100%;max-height:190px;display:block}.chart rect{fill:#a99ce7}.chart line{stroke:var(--line)}.chart text{fill:#b7c0d0;font-size:11px}.search{margin:26px 0 14px}footer{display:flex;justify-content:space-between;align-items:center;gap:24px;border-top:1px solid var(--line);padding-top:20px;margin-top:48px;color:var(--muted);font-size:.7rem;line-height:1.6}footer>span{max-width:65ch}footer button{flex-shrink:0}@media(hover:hover)and(pointer:fine){button:not(:disabled):hover{background:#373247}.primary:not(:disabled):hover{background:#cbc4ff}.queue:hover{color:#d2c9ff}}@media(max-width:850px){.case-layout{grid-template-columns:1fr;gap:30px}aside{padding:24px 0 0;border:0;border-top:1px solid var(--line)}.portal-links{grid-template-columns:repeat(auto-fit,minmax(170px,1fr))}}@media(max-width:600px){.medicine{padding:20px 8px 100px}header{align-items:flex-start;flex-direction:column;gap:22px}.total{grid-template-columns:auto auto;align-items:baseline;gap:5px 12px}.total small{grid-column:1/-1}.heading-line{align-items:flex-start;flex-direction:column;gap:8px}.settings{grid-template-columns:1fr}.settings label:last-child{grid-column:auto}.timer,footer{align-items:flex-start;flex-direction:column}.next{padding:16px}.views{gap:2px}.views button{font-size:.75rem;padding:9px 11px}}@media(prefers-reduced-motion:reduce){button{transition:none}button:active{transform:none}}
</style>
